let detailMode='all';
function htmlEscape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function greatCircle(a,b){const r=Math.PI/180,dlat=(b[2]-a[2])*r,dlon=(b[1]-a[1])*r;const h=Math.sin(dlat/2)**2+Math.cos(a[2]*r)*Math.cos(b[2]*r)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))}
function distanceText(km){if(km<.5)return '< 1 <em>km</em>';return Math.round(km).toLocaleString('ko-KR')+' <em>km</em>'}
function imageCredit(m){return `<a href="${htmlEscape(m.source)}" target="_blank" rel="noopener">원본·출처</a> · ${htmlEscape(m.artist)} · ${m.licenseUrl?`<a href="${htmlEscape(m.licenseUrl)}" target="_blank" rel="noopener">${htmlEscape(m.license)}</a>`:htmlEscape(m.license)}${m.date?`<br><small>자료에 기재된 날짜: ${htmlEscape(m.date)}</small>`:''}`}
function imageFigure(id,m,caption,kind){const f=$(id);f.innerHTML='';if(!m||!m.local){f.innerHTML='<div class="photo-fallback">이 자료는 아직 이미지를 준비하지 못했습니다. 아래 지역 출처에서 자세히 살펴보세요.</div>';return}const button=document.createElement('button');button.className='enlarge-photo';button.setAttribute('aria-label',caption+' — 크게 보기');const img=document.createElement('img');img.src=m.local;img.alt=caption;img.loading='lazy';img.decoding='async';button.append(img);button.onclick=()=>showImage(m,caption);const label=document.createElement('span');label.className='image-kind';label.textContent=kind;const cap=document.createElement('figcaption');cap.innerHTML=`<p>${htmlEscape(caption)}</p>${imageCredit(m)}`;img.onerror=()=>{button.hidden=true;label.textContent='이미지를 불러오지 못했습니다';};f.append(button,label,cap)}
function showImage(m,caption){let dlg=$('image-viewer');if(!dlg){dlg=document.createElement('dialog');dlg.id='image-viewer';document.body.append(dlg)}dlg.innerHTML='';const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','이미지 닫기');close.onclick=()=>dlg.close();const img=document.createElement('img');img.src=m.local;img.alt=caption;const p=document.createElement('p');p.innerHTML=htmlEscape(caption)+'<br>'+imageCredit(m);dlg.append(close,img,p);dlg.showModal()}
function detailFilter(mode){detailMode=mode;document.querySelectorAll('[data-detail-tab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.detailTab===mode));document.querySelectorAll('[data-detail-panel]').forEach(p=>{p.hidden=mode!=='all'&&p.dataset.detailPanel!==mode;p.classList.toggle('single-panel',mode!=='all')})}
function geoVisual(j,idx,p){const stops=j.stops;const ids=[...new Set([Math.max(0,idx-1),idx,Math.min(stops.length-1,idx+1)])];const a=ids.map(i=>stops[i]);const xs=a.map(s=>s[1]),ys=a.map(s=>s[2]);const mx=(Math.min(...xs)+Math.max(...xs))/2,my=(Math.min(...ys)+Math.max(...ys))/2;const scale=Math.min(330/Math.max(.05,Math.max(...xs)-Math.min(...xs)),140/Math.max(.05,Math.max(...ys)-Math.min(...ys)));const points=a.map(s=>[250+(s[1]-mx)*scale,140-(s[2]-my)*scale]);let svg=`<svg viewBox="0 0 500 280" role="img" aria-label="${htmlEscape(p.title)}와 앞뒤 주요 장소의 위치 관계"><defs><pattern id="detail-grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#cbd2bd" stroke-width=".5"/></pattern></defs><rect width="500" height="280" fill="#e7ebdc"/><rect width="500" height="280" fill="url(#detail-grid)"/><path d="M0 240Q90 70 180 180T500 100M0 260Q90 120 180 220T500 150M0 200Q100 20 200 130T500 45" fill="none" stroke="#c2cbb5" stroke-width="1" opacity=".55"/>`;
svg+=`<path d="${points.map((c,i)=>(i?'L':'M')+c.join(',')).join(' ')}" fill="none" stroke="#b2976d" stroke-width="1.5" stroke-dasharray="5 5"/>`;
ids.forEach((i,n)=>{const [x,y]=points[n];const active=i===idx;svg+=`<circle cx="${x}" cy="${y}" r="${active?14:8}" fill="${active?'#ad7b4d':'#839279'}" stroke="#f6f5ed" stroke-width="3"/><text x="${x}" y="${y+4}" fill="white" text-anchor="middle" font-size="9">${i+1}</text><text x="${Math.min(435,Math.max(65,x))}" y="${y-24}" text-anchor="middle" fill="#435642" font-size="12" font-family="sans-serif">${htmlEscape(stops[i][0])}</text>`});svg+=`<text x="468" y="35" fill="#7e8e73" font-size="11">N ↑</text><text x="22" y="260" fill="#7e8e73" font-size="9">${stops[idx][2].toFixed(3)}° N · ${stops[idx][1].toFixed(3)}° E · 대표 좌표</text></svg>`;return '<span class="geo-title">성경 속 장소의 위치 관계</span>'+svg}
function sceneDiagram(id,e,s){const f=$('scene-figure');const flow=e.flow;let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 420" role="img" aria-label="${htmlEscape(s[3])} 사건 흐름도"><rect width="640" height="420" fill="#eae8dc"/><path d="M0 290Q130 120 260 270T640 210L640 420H0Z" fill="#d7dccb"/><path d="M0 330Q160 230 320 340T640 290L640 420H0Z" fill="#c5ceba"/><circle cx="510" cy="88" r="35" fill="#c2a57b" opacity=".4"/><text x="45" y="55" fill="#9e7952" font-size="12" letter-spacing="3">BIBLICAL STORY / ${htmlEscape(s[5])}</text><text x="45" y="100" fill="#354c3c" font-size="24" font-family="serif">${htmlEscape(s[3])}</text><path d="M100 220H540" fill="none" stroke="#b29973" stroke-width="2" stroke-dasharray="5 5"/>`;
flow.forEach((v,i)=>{const x=100+i*220;svg+=`<circle cx="${x}" cy="220" r="38" fill="#f6f4ea" stroke="#a6b095"/><text x="${x}" y="228" text-anchor="middle" fill="#a77d4c" font-family="serif" font-size="25">${i+1}</text><text x="${x}" y="288" text-anchor="middle" fill="#3d5540" font-size="15">${htmlEscape(v)}</text>`});svg+='<text x="45" y="385" fill="#64765c" font-size="11">성경 본문의 사건 순서를 정리한 도해 · 실제 풍경이나 고증 복원도가 아닙니다</text></svg>';f.innerHTML=`<div class="scene-diagram">${svg}</div><figcaption><p>성경 본문 요약으로 구성한 사건 흐름도입니다.</p>말씀의 여정 제작 · 후대 성경 미술 자료가 없는 장면을 도해로 안내합니다.</figcaption>`}
function renderDetails(pi,idx){const j=journeys[pi],s=j.stops[idx],e=eventDetails[pi][idx],p=places[placeIds[pi][idx]];const first=idx===0,last=idx===j.stops.length-1;let cum=0;for(let n=1;n<=idx;n++)cum+=greatCircle(j.stops[n-1],j.stops[n]);$('detail-heading').textContent=s[0]+'을 더 깊이 살펴보기';$('detail-location').textContent=p.modernName;$('detail-counter').textContent=String(idx+1).padStart(2,'0');$('distances').innerHTML=`<div class="distance-card"><small>이전 주요 지점에서 · 직선거리</small><strong>${first?'출발지':distanceText(greatCircle(j.stops[idx-1],s))}</strong><span>${first?j.name+' 여정의 첫 장면':htmlEscape(j.stops[idx-1][0]+' → '+s[0])}</span></div><div class="distance-card"><small>다음 주요 지점까지 · 직선거리</small><strong>${last?'마지막 장면':distanceText(greatCircle(s,j.stops[idx+1]))}</strong><span>${last?'이 지도에서 선별한 여정의 끝':htmlEscape(s[0]+' → '+j.stops[idx+1][0])}</span></div><div class="distance-card"><small>출발부터 여기까지 · 연결선 거리 합계</small><strong>${idx===0?'0 <em>km</em>':distanceText(cum)}</strong><span>실제 누적 이동거리와 다름 · 생략된 경유지 제외</span></div>`;$('ancient-text').textContent=p.ancient;$('certainty').textContent=p.certainty;$('ancient-visual').innerHTML=geoVisual(j,idx,p);$('modern-name').textContent=p.modernName;$('modern-text').textContent=p.present;$('modern-map').href=`https://www.google.com/maps/search/?api=1&query=${s[2]},${s[1]}`;imageFigure('modern-figure',p.photo,p.photo.caption||p.photoCaption,p.photo.kind||'현대 지역 사진 · 촬영 당시 기록');$('scene-title').textContent=s[3];$('scene-body').innerHTML=e.paragraphs.map(t=>`<p>${htmlEscape(t)}</p>`).join('');$('reading-note').textContent=e.note;$('detail-scripture').textContent=e.reference;$('detail-bible').href='https://www.bskorea.or.kr/bible/korbibReadpage.php';const art=artwork[e.art];if(art&&art.local)imageFigure('scene-figure',art,art.caption,'성경 미술 · 후대의 해석');else sceneDiagram('scene-figure',e,s);$('detail-sources').innerHTML='<ul>'+p.sources.map(src=>`<li><a href="${htmlEscape(src.url)}" target="_blank" rel="noopener">${htmlEscape(src.title)} ↗</a></li>`).join('')+'</ul><p><b>지역 사진</b><br>'+imageCredit(p.photo)+'</p>'+(art&&art.local?'<p><b>성경 미술</b><br>'+htmlEscape(art.caption)+'<br>'+imageCredit(art)+'</p>':'<p><b>사건 흐름도</b> · 표시한 성경 본문을 바탕으로 직접 구성했습니다.</p>');document.querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>detailFilter(b.dataset.detailTab));detailFilter(detailMode);let link=$('detail-jump');if(!link){link=document.createElement('a');link.id='detail-jump';link.className='detail-anchor';link.href='#place-details';$('event-place').after(link)}link.textContent='지역·사진·이동거리 자세히 보기 ↓'}
